"use client";
import { useEffect, useState } from "react";

const DESIGN_WIDTH = 1146;
const DESIGN_HEIGHT = 2100;

function CalendarWidget({ onDateSelect }: { onDateSelect: (date: string) => void }) {
  const monthNames = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const [month, setMonth] = useState(8);
  const [year, setYear] = useState(2025);
  const [selected, setSelected] = useState<number | null>(null);

  const getDays = (y: number, m: number) => new Date(y, m + 1, 0).getDate();
  const getFirst = (y: number, m: number) => new Date(y, m, 1).getDay();

  const totalDays = getDays(year, month);
  const firstDay = getFirst(year, month);

  const cells: (number | null)[] = Array(firstDay).fill(null);
  for (let d = 1; d <= totalDays; d++) cells.push(d);
  while (cells.length % 7 !== 0) cells.push(null);

  const rows: (number | null)[][] = [];
  for (let i = 0; i < cells.length; i += 7) rows.push(cells.slice(i, i + 7));

  const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
  const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

  const today = new Date();
  const isToday = (d: number | null) => d !== null && d === today.getDate() && month === today.getMonth() && year === today.getFullYear();

  return (
    <div style={{ fontFamily: "Arial, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "16px" }}>
        <button onClick={prevMonth} style={{ background: "none", border: "none", cursor: "pointer", fontSize: "20px", color: "#333", padding: "0 4px" }}>‹</button>
        <select value={month} onChange={e => setMonth(+e.target.value)} style={{ padding: "4px 8px", borderRadius: "6px", border: "1px solid #bbb", fontSize: "14px", background: "#fff" }}>
          {monthNames.map((name, i) => <option key={i} value={i}>{name}</option>)}
        </select>
        <select value={year} onChange={e => setYear(+e.target.value)} style={{ padding: "4px 8px", borderRadius: "6px", border: "1px solid #bbb", fontSize: "14px", background: "#fff" }}>
          {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
        </select>
        <button onClick={nextMonth} style={{ background: "none", border: "none", cursor: "pointer", fontSize: "20px", color: "#333", padding: "0 4px" }}>›</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", textAlign: "center", marginBottom: "8px" }}>
        {["Su","Mo","Tu","We","Th","Fr","Sa"].map(d => (
          <div key={d} style={{ fontSize: "12px", color: "#888", fontWeight: 600, padding: "4px 0" }}>{d}</div>
        ))}
      </div>
      {rows.map((row, ri) => (
        <div key={ri} style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", textAlign: "center", marginBottom: "4px" }}>
          {row.map((day, di) => (
            <div key={di}
              onClick={() => { if (day) { setSelected(day); onDateSelect(`${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`); } }}
              style={{
                width: "34px", height: "34px",
                display: "flex", alignItems: "center", justifyContent: "center",
                margin: "0 auto",
                borderRadius: "50%",
                cursor: day ? "pointer" : "default",
                background: day === selected ? "#333" : "transparent",
                color: day === selected ? "#fff" : day ? "#333" : "transparent",
                fontSize: "14px",
                border: isToday(day) && day !== selected ? "2px solid #333" : "2px solid transparent",
              }}
            >{day ?? ""}</div>
          ))}
        </div>
      ))}
    </div>
  );
}

type Product = { id: number; name: string; description: string; price: number };

function ScrollColumn({ max, value, onChange }: { max: number; value: number; onChange: (v: number) => void }) {
  const items = Array.from({ length: max }, (_, i) => i);
  const ITEM_H = 40;
  return (
    <div style={{ flex: 1, overflowY: "scroll", height: `${ITEM_H}px`, scrollSnapType: "y mandatory", scrollbarWidth: "none" }}>
      {items.map(i => (
        <div
          key={i}
          onClick={() => onChange(i)}
          style={{
            height: `${ITEM_H}px`, display: "flex", alignItems: "center", justifyContent: "center",
            scrollSnapAlign: "center", cursor: "pointer",
            fontFamily: "var(--font-azeret-mono), 'Azeret Mono', monospace",
            fontWeight: 800, fontSize: "20px",
            color: i === value ? "#1E1E1E" : "#888",
            background: i === value ? "#A0A0A0" : "transparent",
            borderRadius: "8px",
          }}
        >{String(i).padStart(2, "0")}</div>
      ))}
    </div>
  );
}

function TimePicker({ value, onChange }: { value: { h: number; m: number }; onChange: (v: { h: number; m: number }) => void }) {
  return (
    <div style={{
      flex: 1, background: "#C4C4C4", borderRadius: "10px", padding: "6px 10px",
      display: "flex", alignItems: "center", gap: "4px",
    }}>
      <ScrollColumn max={24} value={value.h} onChange={h => onChange({ ...value, h })} />
      <span style={{ fontWeight: 800, fontSize: "20px", color: "#555" }}>:</span>
      <ScrollColumn max={60} value={value.m} onChange={m => onChange({ ...value, m })} />
    </div>
  );
}

